import java.io.IOException;

public class Main {
    private static long rowTime(long n) {
        long block = (n - 1) / 4;
        long pos = (n - 1) % 4;
        long base = block * 8;
        if (pos == 0) return base + 1;
        if (pos == 1) return base + 3;
        if (pos == 2) return base + 5;
        return base + 7;
    }

    private static int seatOffset(char s) {
        switch (s) {
            case 'f': return 0;
            case 'e': return 1;
            case 'd': return 2;
            case 'a': return 3;
            case 'b': return 4;
            case 'c': return 5;
        }
        return 0;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String input = br.readLine().trim();
        int len = input.length();
        char seat = input.charAt(len - 1);
        long n = Long.parseLong(input.substring(0, len - 1));
        long result = rowTime(n) + seatOffset(seat);
        System.out.println(result);
    }
}

import java.io.BufferedReader;
