import java.io.IOException;

public class Main {
    private static long baseTime(long n) {
        long k = (n - 1) / 4;
        long t = 0;
        if (k > 0) {
            t += 6;            // rows 1 and 3
            t += (k - 1) * 14; // full cycles of 4 rows
        }
        long r = n - 4 * k;
        if (r == 1) {
            // already accounted row 1
        } else if (r == 2) {
            t += 7;  // move + serve row 2
        } else if (r == 3) {
            t += 6;  // serve row 3
        } else { // r == 4
            t += 13; // move + serve row 4
        }
        return t;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();

        int len = s.length();
        char seat = s.charAt(len - 1);
        long n = Long.parseLong(s.substring(0, len - 1));

        long time = baseTime(n);

        int offset;
        switch (seat) {
            case 'f': offset = 1; break;
            case 'e': offset = 2; break;
            case 'd': offset = 3; break;
            case 'a': offset = 4; break;
            case 'b': offset = 5; break;
            default:  offset = 6; // 'c'
        }

        System.out.println(time + offset);
    }
}

