import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    // Precomputed pattern of row differences between attendants' moves
    private static final int[] diffs = {2, 1, 3, 1};

    private static long timeToReachRow(long n) {
        if (n == 1) return 0; // already at row 1, no movement time

        long row = 1;
        long time = 0;
        int idx = 0;

        while (row < n) {
            long diff = diffs[idx];
            long nextRow = row + diff;
            if (nextRow > n) {
                // Move only as much as needed to reach row n
                long delta = n - row;
                time += delta; // 1 second per row moved
                row = n;
                break;
            } else {
                time += diff;
                row = nextRow;
            }
            idx = (idx + 1) % diffs.length;
        }
        return time;
    }

    private static long seatOffset(char seat) {
        switch (seat) {
            case 'f': return 1;
            case 'e': return 2;
            case 'd': return 3;
            case 'a': return 4;
            case 'b': return 5;
            case 'c': return 6;
            default: return 0; // should not happen for valid input
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String input = br.readLine().trim();

        int len = input.length();
        char seat = input.charAt(len - 1);
        long n = Long.parseLong(input.substring(0, len - 1));

        long movementTime = timeToReachRow(n);
        long servingTime = seatOffset(seat);

        long result = movementTime + servingTime;
        System.out.println(result);
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String input = br.readLine().trim();

        int len = input.length();
        char seat = input.charAt(len - 1);
        long n = Long.parseLong(input.substring(0, len - 1));

        long ans = 0;

        // Determine which attendant serves row n and compute time until they start row n
        if (n % 2 == 1) {
            // Odd row: first attendant
            long k = (n + 1) / 2; // this is the k-th row served by first attendant
            long cycles = (k - 1) / 2;
            long posInCycle = (k - 1) % 2;

            long rowsServedBeforeCycle = 4 * cycles; // each cycle: 4 rows served by each attendant
            long timeBeforeCycle = rowsServedBeforeCycle * 6 + cycles * 4; // 6s per row + 4s moves per cycle

            long timeBeforeRow;
            if (posInCycle == 0) {
                // first row in cycle: pattern 1,3 then 2,4 then +3 rows
                // first attendant rows: 1,2,5,6,...; difference pattern: +1,+3,+1,+3...
                // within cycle, first row is served immediately after previous cycle
                timeBeforeRow = timeBeforeCycle;
            } else {
                // second row in cycle: first attendant moves 1 row (1s) after serving previous row
                timeBeforeRow = timeBeforeCycle + 6 + 1; // serve previous row (6s) + move 1 row (1s)
            }

            ans = timeBeforeRow;
        } else {
            // Even row: second attendant
            long k = n / 2; // this is the k-th row served by second attendant
            long cycles = (k - 1) / 2;
            long posInCycle = (k - 1) % 2;

            long rowsServedBeforeCycle = 4 * cycles;
            long timeBeforeCycle = rowsServedBeforeCycle * 6 + cycles * 4;

            long timeBeforeRow;
            if (posInCycle == 0) {
                // first row in cycle for second attendant
                // second attendant starts serving its first row in cycle after:
                // - first attendant serves its first row in cycle (6s)
                // - second attendant moves to its row (1s)
                timeBeforeRow = timeBeforeCycle + 6 + 1;
            } else {
                // second row in cycle for second attendant
                // second attendant serves previous row (6s) then moves 1 row (1s)
                timeBeforeRow = timeBeforeCycle + 6 + 1 + 6 + 1;
            }

            ans = timeBeforeRow;
        }

        // Add time to reach specific seat in the row
        // Serving order: f(1), e(2), d(3), a(4), b(5), c(6)
        int seatTime;
        switch (seat) {
            case 'f': seatTime = 1; break;
            case 'e': seatTime = 2; break;
            case 'd': seatTime = 3; break;
            case 'a': seatTime = 4; break;
            case 'b': seatTime = 5; break;
            case 'c': seatTime = 6; break;
            default: seatTime = 0;
        }

        ans += seatTime;

        System.out.println(ans);
    }
}

